import{_ as e,o as a,c as s,a5 as d}from"./chunks/framework.DGp912Ge.js";const g=JSON.parse('{"title":"High Level Command — C++ 예제","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/software/sdk/cpp/high-level.md","filePath":"ko/software/sdk/cpp/high-level.md","lastUpdated":1785209608000}'),i={name:"ko/software/sdk/cpp/high-level.md"};function o(l,t,n,h,r,c){return a(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="high-level-command-—-c-예제" tabindex="-1">High Level Command — C++ 예제 <a class="header-anchor" href="#high-level-command-—-c-예제" aria-label="Permalink to &quot;High Level Command — C++ 예제&quot;">​</a></h1><p><strong>소스</strong>: <code>rbq_sdk/cpp/example/src/rbq_high_level.cpp</code></p><p>DDS를 통해 <code>HighLevelCommand</code> 메시지를 <strong>50 Hz</strong>로 발행합니다.<br> 보행 선택은 터미널 입력으로, 속도 setpoint는 조이스틱으로 제어합니다.</p><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>세 가지 동시 실행 구성요소:</p><table tabindex="0"><thead><tr><th>구성요소</th><th>주기</th><th>역할</th></tr></thead><tbody><tr><td><strong>제어 루프 스레드</strong></td><td>50 Hz</td><td>현재 보행 + 속도로 <code>HighLevelCommand</code> 발행</td></tr><tr><td><strong>조이스틱 루프 스레드</strong></td><td>100 Hz</td><td>조이스틱 폴링 후 속도 전역 변수 업데이트</td></tr><tr><td><strong>메인 스레드</strong> (터미널)</td><td>블로킹</td><td>stdin에서 보행 이름/ID를 읽어 목표 보행 업데이트</td></tr></tbody></table><p>시작 시 제어 루프가 <code>switchControlMode = true</code>를 한 번 발행하여 로봇 스택에서 <strong>EXT_JOY 모드</strong>를 활성화합니다 — 이 토픽이 발행되지 않으면 <code>HighLevelCommand</code> 토픽은 무시됩니다.</p><h2 id="사전-요구사항" tabindex="-1">사전 요구사항 <a class="header-anchor" href="#사전-요구사항" aria-label="Permalink to &quot;사전 요구사항&quot;">​</a></h2><ul><li>RBQ SDK 빌드 및 설치 완료 — <a href="/RBQ/ko/software/sdk/cpp/overview.html">C++ SDK 개요</a> 참조.</li><li>Linux 조이스틱 장치 <code>/dev/input/js*</code> (조이스틱이 <strong>필수</strong>).</li><li>로봇 스택이 실행 중(시뮬레이션 또는 하드웨어).</li></ul><h2 id="빌드" tabindex="-1">빌드 <a class="header-anchor" href="#빌드" aria-label="Permalink to &quot;빌드&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/setup.bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build.bash</span></span></code></pre></div><p>바이너리: <code>bin/rbq_high_level</code></p><h2 id="실행" tabindex="-1">실행 <a class="header-anchor" href="#실행" aria-label="Permalink to &quot;실행&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_high_level</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">networkInterfac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [joystickPath]</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 예:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_high_level</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_high_level</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/input/js1</span></span></code></pre></div><p>조이스틱 자동 감지는 Sport Client (조이스틱) 예제와 동일한 로직을 따릅니다.</p><h2 id="터미널-명령" tabindex="-1">터미널 명령 <a class="header-anchor" href="#터미널-명령" aria-label="Permalink to &quot;터미널 명령&quot;">​</a></h2><p><code>&gt;</code> 프롬프트에서 <strong>보행 이름</strong> 또는 <strong>숫자 보행 ID</strong>를 입력합니다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>list              # 예제 내장 목록 출력</span></span>
<span class="line"><span>standing          # STANDING으로 전환 (이름으로)</span></span>
<span class="line"><span>3                 # TROTTING으로 전환 (ID로)</span></span>
<span class="line"><span>waving            # WAVING으로 전환 (이름으로)</span></span></code></pre></div><h2 id="지원-보행-목록" tabindex="-1">지원 보행 목록 <a class="header-anchor" href="#지원-보행-목록" aria-label="Permalink to &quot;지원 보행 목록&quot;">​</a></h2><table tabindex="0"><thead><tr><th>이름</th><th>ID</th><th>설명</th></tr></thead><tbody><tr><td><code>sitting</code></td><td>0</td><td>지면에 앉기</td></tr><tr><td><code>standing</code></td><td>1</td><td>서기 자세 (시작 시 기본값)</td></tr><tr><td><code>trotting</code></td><td>3</td><td>MPC 트롯 보행</td></tr><tr><td><code>trot_stairs</code></td><td>4</td><td>계단 적응형 트롯</td></tr><tr><td><code>waving</code></td><td>5</td><td>느린 걷기 보행</td></tr><tr><td><code>docking</code></td><td>10</td><td>자동 도킹 시퀀스</td></tr></tbody></table><blockquote><p>예제 내장 목록에는 지원하지 않는 내부 보행도 함께 출력됩니다. 위 표의 보행만 사용하세요.</p></blockquote><h2 id="조이스틱-속도-제어" tabindex="-1">조이스틱 속도 제어 <a class="header-anchor" href="#조이스틱-속도-제어" aria-label="Permalink to &quot;조이스틱 속도 제어&quot;">​</a></h2><table tabindex="0"><thead><tr><th>축</th><th>매핑</th><th>최대값</th></tr></thead><tbody><tr><td>왼쪽 스틱 Y (앞으로)</td><td><code>vel_x</code></td><td>±1.2 m/s</td></tr><tr><td>왼쪽 스틱 X (왼쪽으로)</td><td><code>vel_y</code></td><td>±0.5 m/s</td></tr><tr><td>오른쪽 스틱 X (요)</td><td><code>omega_z</code></td><td>±60 deg/s</td></tr></tbody></table><p>데드존: <strong>0.12</strong> 적용 후 스케일링.</p><blockquote><p><strong><code>omega_z</code> 단위 주의</strong>: <code>HighLevelCommand.omega_z</code>는 <strong>도/초(deg/s)</strong> 단위로 전송됩니다.<br> 로봇 내부 QuadWalk가 D2R을 곱해 rad/s로 변환합니다 (예: 60 deg/s ≈ 1.05 rad/s 요 속도).</p></blockquote><h2 id="사용되는-dds-토픽" tabindex="-1">사용되는 DDS 토픽 <a class="header-anchor" href="#사용되는-dds-토픽" aria-label="Permalink to &quot;사용되는 DDS 토픽&quot;">​</a></h2><table tabindex="0"><thead><tr><th>방향</th><th>토픽</th><th>메시지 타입</th></tr></thead><tbody><tr><td>발행</td><td><code>rt/rbq/cmd/high_level</code></td><td><code>rbq_msgs::msg::dds_::HighLevelCommand_</code></td></tr><tr><td>발행</td><td><code>rt/rbq/cmd/switch_control_mode</code></td><td><code>std_msgs::msg::dds_::Bool_</code></td></tr></tbody></table><h2 id="주요-구현-사항" tabindex="-1">주요 구현 사항 <a class="header-anchor" href="#주요-구현-사항" aria-label="Permalink to &quot;주요 구현 사항&quot;">​</a></h2><ul><li><strong><code>gait_transition</code> 플래그</strong>: 보행 변경 직후 단 한 틱에만 <code>true</code>로 설정되며, <code>std::atomic&lt;bool&gt;::exchange()</code>로 정확히 한 번만 소비됩니다. QuadWalk <code>gaitTimer</code>가 연속으로 트리거되는 것을 방지합니다.</li><li><strong><code>switchControlMode</code></strong>: 시작 시 200 ms 딜레이 후 한 번 발행됩니다 (DDS 구독자 연결 대기). 발행하지 않으면 로봇은 조이스틱 모드를 유지하고 <code>HighLevelCommand</code>를 무시합니다.</li><li><strong>타이밍</strong>: 제어 루프는 <code>clock_nanosleep(CLOCK_REALTIME, TIMER_ABSTIME, ...)</code>을 사용해 정밀한 20 ms 스케줄링을 구현합니다.</li></ul><h2 id="관련-문서" tabindex="-1">관련 문서 <a class="header-anchor" href="#관련-문서" aria-label="Permalink to &quot;관련 문서&quot;">​</a></h2><ul><li><a href="/RBQ/ko/software/sdk/cpp/sport-client.html">Sport Client</a></li><li><a href="/RBQ/ko/software/sdk/cpp/sport-client-joy.html">Sport Client (조이스틱)</a></li><li><a href="/RBQ/ko/software/sdk/cpp/low-level.html">Low Level (RL 정책)</a></li><li><a href="/RBQ/ko/software/sdk/cpp/overview.html">C++ SDK 개요</a></li></ul>`,31)])])}const k=e(i,[["render",o]]);export{g as __pageData,k as default};
